/**
 * @brief uv_work 处理完成回调，返回执行结果，释放内存
 */
static void __load_after_work_cb(uv_work_t* req, int status)
{
    FileReq* fr = static_cast<FileReq*>(req->data);
    if (!fr)
        return;
    #ifdef CONFIG_QUICKAPP_QUALITY_PROFILER
    PROFILE_FEATURE_MODULE_LOG_END(get_type_name(fr->type), fr->filename);
    #endif
    // 0 表示成功完成
    if (status != 0) {
        __invoke_fr_cb(fr, __error_code_map(status), uv_strerror(status), NULL);
    } else if (fr->r < 0) {
        __invoke_fr_cb(fr, __error_code_map(fr->r), uv_strerror(fr->r), NULL);
    } else if (fr->type == FILE_READTEXT) {
        // 将读取的文件内容写入 String
        system_file_read_txt_succ_t* data = system_fileMallocread_txt_succ_t();
        char* buf = (char*)FeatureMalloc(fr->len + 1, FT_CHAR);
        memcpy(buf, fr->buf, fr->len);
        buf[fr->len] = 0;
        data->text = (const char*)buf;
        __invoke_fr_cb(fr, 0, NULL, data);
    } else if (fr->type == FILE_READARRBUF) {
        // 将读取的文件内容写入ArrayBuffer
        ft_context_ref ft_ctx = FeatureGetContext(fr->handle);
        ft_value_t buffer = ft_from_typed_buffer(ft_ctx, fr->buf, fr->len, FT_Uint8Array);
        system_file_read_arr_buf_succ_t* data = system_fileMallocread_arr_buf_succ_t();
        data->buffer = (ft_value_t*)FeatureMalloc(sizeof(ft_value_t), FT_ANY_REF);
        *(data->buffer) = buffer;
        __invoke_fr_cb(fr, 0, NULL, data);
        ft_free_value(ft_ctx, buffer);
    } else if (fr->type == FILE_WRITETEXT || fr->type == FILE_WRITEARRBUF) {
        __invoke_fr_cb(fr, 0, NULL, NULL);
    }
}

template <typename T>
void __file_load(FeatureInstanceHandle feature, T* param, int type)
{
    int r;
    char* app_path;
    FileContext* fc = getFileContext(feature);
    FileReq* fr = static_cast<FileReq*>(malloc(sizeof(*fr)));
    if (!fr) {
        FILE_ERROR("malloc fail");
        return;
    }
    initFileReq(fr);
    fr->handle = FeatureDupInstanceHandle(feature);
    fr->success = param->success;
    fr->fail = param->fail;
    fr->complete = param->complete;
    fr->type = type;
    fr->pkgname = strdup(fc->pkg_name);
    if (!fc->loop) {
        FILE_ERROR("uvloop is null");
        return __invoke_fr_cb(fr, FT_ERR_GENERAL, "uvloop is null", NULL);
    }

    if (!check_str(param->uri) || ((type == FILE_WRITETEXT || type == FILE_WRITEARRBUF) && is_path_in_tmp(param->uri))) {
        return __invoke_fr_cb(fr, FT_ERR_ARGS, "invalid file path", NULL);
    }
    if (*(param->uri) == '/' && (type == FILE_READTEXT || type == FILE_READARRBUF)) {
        app_path = (char*)malloc(CONFIG_PATH_MAX);
        memset(app_path, 0, CONFIG_PATH_MAX);
#ifdef CONFIG_QUICKAPP
        sprintf(app_path, "%s/app/%s%s", CONFIG_HAP_APP_PATH, fc->pkg_name, param->uri);
#else
        // CONFIG_QUICK_APP 未打开，采取默认值
        sprintf(app_path, "data/app/%s%s", fc->pkg_name, param->uri);
#endif
    } else {
        app_path = app_relative_to_absolute_path(fc->pkg_name, param->uri);
    }

    if (!app_path) {
        FILE_ERROR("invalid file path: %s", param->uri);
        return __invoke_fr_cb(fr, FT_ERR_ARGS, "invalid file path", NULL);
    }

    fr->filename = app_path;
    if constexpr (std::is_same_v<T, system_file_write_text_param_t>) {
        if (!check_str(param->text)) {
            FILE_ERROR("invalid text");
            return __invoke_fr_cb(fr, FT_ERR_ARGS, "invalid text", NULL);
        }
        fr->offset = 0;
        if (param->append) {
            fr->flags = O_APPEND;
        } else {
            fr->flags = O_TRUNC;
        }
        fr->flags |= O_WRONLY | O_CREAT;
        fr->len = strlen(param->text);
        fr->buf = (uint8_t*)FeatureMalloc(fr->len + 1, FT_UINT8);
        memcpy(fr->buf, param->text, fr->len);
    } else if constexpr (std::is_same_v<T, system_file_write_arr_buf_param_t>) {
        ft_context_ref ft_ctx = FeatureGetContext(feature);
        if (!check_any(param->buffer) || (param->position < 0 && !param->append)) {
            FILE_ERROR("invalid argument in writeArrayBuffer");
            return __invoke_fr_cb(fr, FT_ERR_ARGS, "invalid array buffer", NULL);
        }
        fr->offset = param->position;
        if (param->append) {
            fr->flags = O_APPEND;
            fr->offset = 0;
        } else {
            fr->flags = 0;
        }
        fr->flags |= O_WRONLY | O_CREAT;
        ft_type buffer_type = ft_get_type(ft_ctx, *(param->buffer));
        uint8_t* buffer = NULL;
        if (buffer_type == FT_TYPE_BUFFER || buffer_type == FT_TYPE_TYPED_BUFFER) {
            buffer = ft_to_buffer(ft_ctx, &(fr->len), *(param->buffer));
            FILE_DEBUG("got buffer, type: %d, size: %ld", buffer_type, fr->len);
        } else {
            FILE_ERROR("invalid array buffer type");
            return __invoke_fr_cb(fr, FT_ERR_ARGS, "invalid array buffer type", NULL);
        }
        fr->buf = (uint8_t*)FeatureMalloc(fr->len + 1, FT_UINT8);
        memcpy(fr->buf, buffer, fr->len);
    } else if constexpr (std::is_same_v<T, system_file_read_text_param_t>) {
        fr->offset = 0;
        fr->len = INT32_MIN;
        fr->flags = O_RDONLY;
    } else if constexpr (std::is_same_v<T, system_file_read_arr_buf_t>) {
        if (param->position >= 0 && (param->length >= 0 || param->length == INT32_MIN)) {
            fr->offset = param->position;
            fr->flags = O_RDONLY;
            fr->len = param->length;
        } else {
            FILE_ERROR("invalid position or length");
            return __invoke_fr_cb(fr, __error_code_map(-EINVAL), uv_strerror(-EINVAL), NULL);
        }
    }
    #ifdef CONFIG_QUICKAPP_QUALITY_PROFILER
    PROFILE_FEATURE_MODULE_LOG_BEGIN(get_type_name(fr->type), fr->filename);
    #endif
    // 使用 libuv 线程池，处理需要多次回调的接口
    fr->req.data = fr;
    r = uv_queue_work(fc->loop, &fr->req, __load_file_work_cb,
        __load_after_work_cb);
    if (r != 0) {
        FILE_ERROR("execute uv_queue_work fail");
    }
    return;
}

