/**
 * @brief 获取文件信息，返回FileInfo数据结构
 */
static FileInfo* __get_info_c(char* path, FileReq* fr)
{
    struct stat statbuf;
    char* app_path = NULL;
    FileInfo* file_info = (FileInfo*)malloc(sizeof(FileInfo));
    if (file_info == NULL || fr->pkgname == NULL) {
        FILE_ERROR("get info fail: %s", path);
        goto error;
    }

    fr->r = stat(path, &statbuf);
    if (fr->r != 0) {
        fr->r = -errno;
        FILE_ERROR("file doesn't exist, path: %s\n", path);
        goto error;
    }

    app_path = app_absolute_to_relative_path(fr->pkgname, path);
    if (app_path == NULL) {
        FILE_ERROR("src path:%s, pkg:%s\n", path, fr->pkgname);
        goto error;
    }

    weakref_list_initialize(&file_info->dir_list);
    weakref_list_initialize(&file_info->file_node);
    if (S_ISDIR(statbuf.st_mode)) {
        file_info->type = 1;
        file_info->length = 0;
    } else {
        file_info->type = 0;
        file_info->length = statbuf.st_size;
    }
    file_info->uri = app_path;
    file_info->last_modified_time = statbuf.st_mtim.tv_sec;
    file_info->file_num = 0;
    file_info->dir_num = 0;

    return file_info;
error:
    if (file_info) {
        free(file_info);
    }
    return NULL;
}
/**
 * @brief 递归读取文件夹信息，添加到list中
 */
static void __read_dir_c(char* dirname, FileReq* fr, weakref_list_node* dir_list)
{
    DIR* dir;
    struct dirent* entry;
    char path[CONFIG_PATH_MAX];
    FileInfo* file_info = NULL;
    FileInfo* root_file_ptr = weakref_container_of(dir_list, FileInfo, dir_list);
    root_file_ptr->file_num = 0;
    root_file_ptr->dir_num = 0;
    FILE_DEBUG("in __read_dir_c, cur dir = %s", root_file_ptr->uri);

    dir = opendir(dirname);
    if (dir == NULL) {
        fr->r = -errno;
        FILE_ERROR("file opendir failed, error: %d:%s path:%s", errno, uv_strerror(errno), dirname);
        return;
    }

    while ((entry = readdir(dir)) != NULL) {
        if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) {
            continue;
        }

        snprintf(path, sizeof(path), "%s/%s", dirname, entry->d_name);

        file_info = __get_info_c(path, fr);
        if (file_info == NULL) {
            continue;
        }
        if (fr->type == FILE_GET && entry->d_type == DT_DIR && fr->flags == 1) {
            __read_dir_c(path, fr, &file_info->dir_list);
        }
        weakref_list_add_tail(dir_list, &file_info->file_node);

        if (file_info->type == 0) {
            root_file_ptr->file_num++;
        } else {
            root_file_ptr->dir_num++;
        }
        FILE_DEBUG("add child num, file = %s", file_info->uri);
    }
    closedir(dir);
}

/**
 * @brief 文件夹处理 uv_work 回调
 */
static void __load_dir_work_cb(uv_work_t* wk)
{
    FileReq* fr = static_cast<FileReq*>(wk->data);
    if (!fr)
        return;

    fr->r = 0;
    fr->offset = 0;

    switch (fr->type) {
    case FILE_MKDIR:
        __create_dir(fr->filename, fr);
        break;
    case FILE_RMDIR:
        __remove_dir(fr->filename, fr);
        break;
    case FILE_GET:
    case FILE_LIST:
        fr->root_file = __get_info_c(fr->filename, fr);
        if (fr->root_file && fr->root_file->type == 1) {
            __read_dir_c(fr->filename, fr, &fr->root_file->dir_list);
        }
        break;
    }
}
static FtArray* __get_dir_list(FileReq* fr, weakref_list_node* dir_list);

system_file_file_info_t* get_file_info(FileInfo* info)
{
    system_file_file_info_t* file_info = system_fileMallocfile_info_t();
    char* uri = static_cast<char*>(FeatureMalloc(strlen(info->uri) + 1, FT_STRING));
    memcpy(uri, info->uri, strlen(info->uri) + 1);
    file_info->uri = uri;
    file_info->length = info->length;
    file_info->lastModifiedTime = (info->last_modified_time) * 1000LL;
    return file_info;
}

system_file_extended_file_info_t* get_extended_file_info(FileReq* fr, FileInfo* info)
{
    if (!fr || !info)
        return NULL;
    system_file_extended_file_info_t* file_info = system_fileMallocextended_file_info_t();
    char* type = static_cast<char*>(FeatureMalloc(strlen(info->type == 0 ? "file" : "dir") + 1, FT_STRING));
    sprintf(type, info->type == 0 ? "file" : "dir");
    file_info->type = type;
    char* uri = static_cast<char*>(FeatureMalloc(strlen(info->uri) + 1, FT_STRING));
    memcpy(uri, info->uri, strlen(info->uri) + 1);
    file_info->uri = uri;
    file_info->length = info->length;
    file_info->lastModifiedTime = (info->last_modified_time) * 1000LL;
    if (fr->flags) { // recursive == true
        file_info->subFiles = __get_dir_list(fr, &info->dir_list);
    } else {
        file_info->subFiles = system_file_malloc_extended_file_info_t_struct_type_array();
    }

    return file_info;
}

/**
 * @brief 获取FileList
 */
FtArray* __get_dir_list(FileReq* fr, weakref_list_node* dir_list)
{
    if (!dir_list) {
        FILE_ERROR("__get_dir_list failed, path:%s\n", fr->filename);
        return NULL;
    }

    FtArray* array;
    FileInfo* root_file_ptr = weakref_container_of(dir_list, FileInfo, dir_list);
    FILE_DEBUG("=====> __get_dir_list, root_file_ptr->uri = %s, dir_num = %d, file_num = %d", root_file_ptr->uri, root_file_ptr->dir_num, root_file_ptr->file_num);
    if (fr->type == FILE_GET) {
        array = system_file_malloc_extended_file_info_t_struct_type_array();
        array->_size = root_file_ptr->dir_num + root_file_ptr->file_num;
        array->_element = malloc(sizeof(system_file_extended_file_info_t*) * array->_size);
    } else {
        array = system_file_malloc_file_info_t_struct_type_array();
        array->_size = root_file_ptr->file_num;
        array->_element = malloc(sizeof(system_file_file_info_t*) * array->_size);
    }
    FILE_DEBUG("array.size = %d", array->_size);

    int index = 0;
    FileInfo *item, *temp;
    weakref_list_for_every_entry_safe(dir_list, item, temp, FileInfo, file_node)
    {
        if (fr->type == FILE_LIST) {
            if (item->type == 0) {
                system_file_file_info_t* file_info = get_file_info(item);
                FILE_DEBUG("index = %d, get file_info->uri = %s", index, file_info->uri);
                ((system_file_file_info_t**)array->_element)[index++] = file_info;
            }
        } else {
            ((system_file_extended_file_info_t**)array->_element)[index++] = get_extended_file_info(fr, item);
            FILE_DEBUG("index = %d, get file_info->uri: %s", index, ((system_file_extended_file_info_t**)array->_element)[index - 1]->uri);
        }
    }
    return array;
}

/**
 * @brief uv_work 处理完成回调，返回执行结果，释放内存
 */
static void __load_dir_after_work_cb(uv_work_t* req, int status)
{
    FileReq* fr = static_cast<FileReq*>(req->data);
    if (!fr)
        return;

    // 0 表示成功完成
    if (status != 0) {
        FILE_ERROR("file failed: file:%s, errno = %d", fr->filename, fr->r);
        __invoke_fr_cb(fr, __error_code_map(status), uv_strerror(status), NULL);
    } else if (fr->r < 0) {
        FILE_ERROR("file failed: file:%s, errno = %d", fr->filename, fr->r);
        __invoke_fr_cb(fr, __error_code_map(fr->r), uv_strerror(fr->r), NULL);
    } else if (fr->type == FILE_GET) {
        system_file_extended_file_info_t* file_info = get_extended_file_info(fr, fr->root_file);
        __invoke_fr_cb(fr, 0, NULL, file_info);
    } else if (fr->type == FILE_LIST) {
        system_file_list_succ_param* data = system_fileMalloclist_succ_param();
        if (fr->root_file) {
            data->fileList = __get_dir_list(fr, &fr->root_file->dir_list);
        }
        __invoke_fr_cb(fr, 0, NULL, data);
    } else {
        __invoke_fr_cb(fr, 0, NULL, NULL);
    }
}

/**
 * @brief 文件夹处理函数
 */
template <typename T>
static void __dir_load(FeatureInstanceHandle feature, T* param, int type)
{
    int r;
    char* app_path;
    FileContext* fc = getFileContext(feature);
    FileReq* fr = static_cast<FileReq*>(malloc(sizeof(*fr)));
    if (!fr) {
        FILE_ERROR("malloc fail");
        return;
    }
    initFileReq(fr);
    fr->handle = FeatureDupInstanceHandle(feature);
    fr->success = param->success;
    fr->fail = param->fail;
    fr->complete = param->complete;
    fr->type = type;
    fr->pkgname = strdup(fc->pkg_name);

    if (!fc->loop) {
        FILE_ERROR("uvloop is null");
        return __invoke_fr_cb(fr, FT_ERR_GENERAL, "uvloop is null", NULL);
    }

    if (!param->uri || ((type == FILE_MKDIR || type == FILE_RMDIR) && is_path_in_tmp(param->uri))) {
        return __invoke_fr_cb(fr, FT_ERR_ARGS, "invalid path", NULL);
    }
    app_path = app_relative_to_absolute_path(fc->pkg_name, param->uri);
    if (!app_path) {
        FILE_ERROR("invalid file path: %s", param->uri);
        return __invoke_fr_cb(fr, FT_ERR_ARGS, "invalid path", NULL);
    }

    fr->filename = app_path;
    if constexpr (std::is_same_v<T, system_file_list_param_t>) {
        fr->flags = -1;
    } else {
        fr->flags = param->recursive;
    }
    // 使用 libuv 线程池，处理需要多次回调的接口
    fr->req.data = fr;
    r = uv_queue_work(fc->loop, &fr->req, __load_dir_work_cb,
        __load_dir_after_work_cb);
    if (r != 0) {
        FILE_ERROR("execute uv_queue_work fail");
    }
    return;
}

